#[inline]
pub fn size_prefixed_root_as_glx(buf: &[u8]) -> Result<GLX<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root::<GLX>(buf)
}

/// Verifies, with the given options, that a buffer of bytes
/// contains a `GLX` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_glx_unchecked`.
#[inline]
pub fn root_as_glx_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<GLX<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root_with_opts::<GLX<'b>>(opts, buf)
}

/// Verifies, with the given verifier options, that a buffer of
/// bytes contains a size prefixed `GLX` and returns
/// it. Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_glx_unchecked`.
#[inline]
pub fn size_prefixed_root_as_glx_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<GLX<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root_with_opts::<GLX<'b>>(opts, buf)
}

/// Assumes, without verification, that a buffer of bytes contains a GLX and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid `GLX`.
#[inline]
pub unsafe fn root_as_glx_unchecked(buf: &[u8]) -> GLX<'_> {
    unsafe { ::flatbuffers::root_unchecked::<GLX>(buf) }
}

/// Assumes, without verification, that a buffer of bytes contains a size prefixed GLX and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid size prefixed `GLX`.
#[inline]
pub unsafe fn size_prefixed_root_as_glx_unchecked(buf: &[u8]) -> GLX<'_> {
    unsafe { ::flatbuffers::size_prefixed_root_unchecked::<GLX>(buf) }
}

pub const GLX_IDENTIFIER: &str = "$GLX";

#[inline]
pub fn glx_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, GLX_IDENTIFIER, false)
}

#[inline]
pub fn glx_size_prefixed_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, GLX_IDENTIFIER, true)
}

#[inline]
pub fn finish_glx_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<GLX<'a>>
) {
    fbb.finish(root, Some(GLX_IDENTIFIER));
}

#[inline]
pub fn finish_size_prefixed_glx_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<GLX<'a>>
) {
    fbb.finish_size_prefixed(root, Some(GLX_IDENTIFIER));
}
